 impl Options {
+    /// Install the owned fail-stop listener on final DB options before open.
+    ///
+    /// Refuses any existing listener, including installation on a clone of
+    /// already guarded options. Success sets `max_bgerror_resume_count` to zero.
+    /// Non-OK background errors retain their identity and become at least fatal;
+    /// automatic error recovery is vetoed. A failed status-promotion allocation
+    /// terminates the process. Healthy automatic maintenance remains enabled.
+    ///
+    /// Installation failure leaves options unchanged and must prevent opening
+    /// an unguarded database. Do not parse, replace or change these options after
+    /// installation. Clones share sticky failure; each explicitly funded new
+    /// recovery attempt requires fresh options and a fresh guard. Installation
+    /// is a live capability that OPTIONS serialization does not restore.
+    ///
+    /// This supports the default local POSIX profile, not custom file-scoped
+    /// retryable filesystems. It does not cover foreground-only errors, check
+    /// failure before dispatch on the caller's behalf, join work, authorize
+    /// retries, or establish allocated-byte/purge bounds.
+    pub fn install_background_error_guard(&mut self) -> Result<BackgroundErrorGuard, Error> {
+        let inner =
+            unsafe { ffi::rocksdb_bigbrotr_options_install_background_error_guard(self.inner) };
+        NonNull::new(inner)
+            .map(|inner| BackgroundErrorGuard { inner })
+            .ok_or_else(|| {
+                Error::new(
+                    "Could not install background-error guard: existing listener or native allocation failure"
+                        .to_owned(),
+                )
+            })
+    }
