+/// Sticky failure query for the owned native background-error listener.
+///
+/// Obtained from [`Options::install_background_error_guard`]. The native listener
+/// remains installed when this handle is dropped. Options clones and databases
+/// opened from them share its failure state, with no reset. Querying after the
+/// Options or database is dropped is safe. A false query is not an atomic permit
+/// to dispatch work and does not cover foreground-only errors.
+pub struct BackgroundErrorGuard {
+    inner: NonNull<ffi::rocksdb_bigbrotr_background_error_guard_t>,
+}
+
+// SAFETY: this owns one opaque handle. Moving it does not move native state.
+// The listener and handle independently own shared_ptr references; callbacks
+// write only the sticky atomic (release), and queries read it (acquire). Rust's
+// shared borrow prevents Drop from racing a query. No Rust callback is retained.
+unsafe impl Send for BackgroundErrorGuard {}
+unsafe impl Sync for BackgroundErrorGuard {}
+
+impl BackgroundErrorGuard {
+    /// Whether any background error or attempted automatic recovery was latched.
+    /// Failure never clears, including after database close.
+    pub fn failed(&self) -> bool {
+        unsafe { ffi::rocksdb_bigbrotr_background_error_guard_failed(self.inner.as_ptr()) != 0 }
+    }
+}
+
+impl Drop for BackgroundErrorGuard {
+    fn drop(&mut self) {
+        unsafe { ffi::rocksdb_bigbrotr_background_error_guard_destroy(self.inner.as_ptr()) }
+    }
+}
